* { box-sizing: border-box; }
body { margin: 0; min-height: 100vh; }
.layout { max-width: 850px; margin: 0 auto; padding: 0 28px 64px; }
.topbar { height: 76px; display: flex; align-items: center; border-bottom: 1px solid #e2e7ed; }
.brand { color: #17202b; font-weight: 750; font-size: 20px; letter-spacing: -.03em; text-decoration: none; }
#app { padding-top: 54px; }
