.project-name { font-weight: 650; overflow-wrap: anywhere; }
.project-row button { background: #edf3fc; color: #2059ad; }
.project-row button:hover { background: #dce9fb; }
.alert { max-width: 620px; margin: -20px 0 22px; padding: 11px 13px; color: #a12828; background: #fff0f0; border: 1px solid #f0cccc; border-radius: 7px; }
.back-button { margin-bottom: 28px; background: #edf3fc; color: #2059ad; }
.empty { color: #667386; font-size: 15px; }
@media (max-width: 540px) { .layout { padding: 0 18px 40px; } #app { padding-top: 38px; } .create-form { align-items: stretch; flex-direction: column; } .create-form button { align-self: flex-start; } h1 { font-size: 30px; } }
